<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import AppIcon from './AppIcon.vue'
import AppModal from './AppModal.vue'
import JsonAssertionsEditor from './JsonAssertionsEditor.vue'
import KeyValueEditor from './KeyValueEditor.vue'
import type {Kind,StepMapping} from '../types'
import catalog from '../stepCatalog.json'
const props=defineProps<{modelValue:Record<string,any>[];kind:Kind;source?:string;mapping?:StepMapping[];previewError?:string;previewPending?:boolean}>()
const emit=defineEmits<{(e:'update:modelValue',value:Record<string,any>[]):void;(e:'validity',valid:boolean):void}>()
const labels:Record<string,string>=Object.fromEntries(Object.values(catalog).flat().map(item=>[item.action,item.label]))
const choices=computed(()=>catalog[props.kind].map(item=>item.action))
const selected=ref(''),expanded=ref(''),sourceOpen=ref('')
const insertInto=ref(''),insertAfter=ref(''),pickerOpen=ref(false),actionQuery=ref(''),requestTab=ref('params'),folded=ref<Set<string>>(new Set()),bodyDraft=ref<Record<string,string>>({})
const starts=['if','repeat','foreach','once','transaction']
const invalidBodies=new Set<string>()
const selectionError=ref('')
function update(){emit('update:modelValue',props.modelValue.map(s=>({...s})))}
function blockEnd(index:number){let level=0;for(let i=index;i<props.modelValue.length;i++){const action=props.modelValue[i]!.action;if(starts.includes(action))level++;if(action==='end'&&--level===0)return i}return index}
function ownerEnd(index:number){const stack:number[]=[];for(let i=0;i<=index;i++){const action=props.modelValue[i]!.action;if(starts.includes(action))stack.push(i);if(action==='end')stack.pop()}return stack.length?blockEnd(stack.at(-1)!):props.modelValue.length}
function depth(index:number){let value=0;for(let i=0;i<index;i++){if(starts.includes(props.modelValue[i]!.action))value++;if(props.modelValue[i]!.action==='end')value--}return Math.max(0,value-(['end','else'].includes(props.modelValue[index]?.action)?1:0))}
function add(){const action=selected.value||choices.value[0]!;if(action==='else'||action==='end')return;const step={id:crypto.randomUUID(),name:labels[action],action,enabled:true,timeout:15000,method:'GET',path:'/',headers:{},params:{},body:null,body_type:'json',source:action==='if'?'variable':action==='assert'?'status':'json',expression:'',variable:action==='foreach'?'item':'',operator:'eq',expected:action==='assert'?200:null,by:props.kind==='app'?'accessibility id':'css',selector:'',role:'button',exact:true,text_exact:false,nth:null,frame:'',query:'path',match_group:0,attribute:'',state:'visible',duration_ms:1000,python:'# 局部扩展；保留正常操作和断言步骤\n',reason:'',count:2,items:[],condition:'visible',tab:'tab2',target_selector:'',uploads:{},columns:'',delimiter:',',ignore_first_line:true,recycle:true,stop_thread:false,share_mode:'all',max_response_ms:null,value:action==='dialog'?'accept':'',direction:'up',expected_status:props.kind==='performance'?200:null,body_pattern:'',extract_json:{},assert_json:{},follow_redirects:null};const steps=[...props.modelValue];const anchor=steps.findIndex(s=>s.id===insertInto.value);const after=steps.findIndex(s=>s.id===insertAfter.value);const at=after>=0?(starts.includes(steps[after]!.action)?blockEnd(after)+1:after+1):anchor<0?steps.length:steps[anchor]!.action==='else'?ownerEnd(anchor):blockEnd(anchor);const additions:Record<string,any>[]=[step];if(starts.includes(action))additions.push({id:crypto.randomUUID(),name:'结束'+labels[action],action:'end',enabled:true});steps.splice(at,0,...additions);emit('update:modelValue',steps);expanded.value=step.id;pickerOpen.value=false;actionQuery.value='';insertAfter.value='';if(starts.includes(action))insertInto.value=step.id}
function addElse(index:number){const end=blockEnd(index);const steps=[...props.modelValue];const marker={id:crypto.randomUUID(),name:'否则执行',action:'else',enabled:true};steps.splice(end,0,marker);emit('update:modelValue',steps);insertInto.value=marker.id;expanded.value=marker.id}
function hasElse(index:number){let level=0;for(let i=index+1;i<blockEnd(index);i++){const action=props.modelValue[i]!.action;if(starts.includes(action))level++;if(action==='end')level--;if(action==='else'&&level===0)return true}return false}
function remove(index:number){const end=starts.includes(props.modelValue[index]!.action)?blockEnd(index):index;for(const s of props.modelValue.slice(index,end+1)){invalidBodies.delete(s.id);invalidBodies.delete(s.id+':assert_json')}if(props.modelValue.slice(index,end+1).some(s=>s.id===insertInto.value))insertInto.value='';emit('validity',invalidBodies.size===0);emit('update:modelValue',props.modelValue.filter((_,i)=>i<index||i>end));if(!props.modelValue.some(s=>s.id===insertInto.value))insertInto.value=''}
function move(index:number,delta:number){const steps=[...props.modelValue];const end=starts.includes(steps[index]!.action)?blockEnd(index):index;let next=delta<0?index-1:end+1;if(next<0||next>=steps.length||steps[next]!.action==='else')return;if(delta<0&&steps[next]!.action==='end'){while(next>=0&&!(starts.includes(steps[next]!.action)&&blockEnd(next)===index-1))next--}if(next<0||steps[next]!.action==='end'||depth(next)!==depth(index))return;const nextEnd=starts.includes(steps[next]!.action)?blockEnd(next):next;if(delta>0)steps.splice(index,nextEnd-index+1,...steps.slice(next,nextEnd+1),...steps.slice(index,end+1));else steps.splice(next,end-next+1,...steps.slice(index,end+1),...steps.slice(next,index));emit('update:modelValue',steps)}
function duplicate(index:number){const steps=[...props.modelValue];const end=starts.includes(steps[index]!.action)?blockEnd(index):index;const copy=JSON.parse(JSON.stringify(steps.slice(index,end+1))) as Record<string,any>[];for(const s of copy)s.id=crypto.randomUUID();copy[0]!.name+='（副本）';steps.splice(end+1,0,...copy);emit('update:modelValue',steps)}
function setItems(s:Record<string,any>,e:Event){const value=(e.target as HTMLTextAreaElement).value;try{s.items=/^\{\{.*\}\}$/.test(value)?value:JSON.parse(value);if(!Array.isArray(s.items)&&typeof s.items!=='string')throw new Error();invalidBodies.delete(s.id);selectionError.value='';emit('validity',invalidBodies.size===0);update()}catch{invalidBodies.add(s.id);emit('validity',false)}}
function bodyText(value:any){return value===null||value===undefined?'':typeof value==='string'?value:JSON.stringify(value,null,2)}
function setBody(s:Record<string,any>,e:Event){const value=(e.target as HTMLTextAreaElement).value;bodyDraft.value[s.id]=value;try{s.body=s.body_type==='json'?(value?JSON.parse(value):null):value;(e.target as HTMLTextAreaElement).setCustomValidity('');invalidBodies.delete(s.id);selectionError.value='';emit('validity',invalidBodies.size===0);update()}catch{invalidBodies.add(s.id);emit('validity',false);(e.target as HTMLTextAreaElement).setCustomValidity('请求体需要有效的 JSON')}}
function setExpected(s:Record<string,any>,e:Event){const value=(e.target as HTMLInputElement).value;try{s.expected=JSON.parse(value)}catch{s.expected=value}update()}
function map(s:Record<string,any>){return props.mapping?.find(m=>m.id===s.id)}
function snippet(s:Record<string,any>){const m=map(s);if(!m?.start||!m.end)return '';return (props.source||'').split('\n').slice(m.start-1,m.end).map((line,i)=>(m.start!+i)+'  '+line).join('\n')}
const noLocator=['goto','assert_url','back','swipe','screenshot','dialog','set_variable','sleep','python','if','else','repeat','foreach','end','once','transaction','csv','open_tab','switch_tab','close_tab','reload']
const visibleSteps=computed(()=>props.modelValue.map((s,i)=>({s,i})).filter(({s,i})=>s.action!=='end'&&!props.modelValue.some((group,index)=>folded.value.has(group.id)&&starts.includes(group.action)&&index<i&&i<blockEnd(index))))
watch(()=>props.modelValue.map(s=>s.id).join(','),()=>{if(!props.modelValue.some(s=>s.id===expanded.value))expanded.value=props.modelValue.find(s=>s.action!=='end')?.id||''},{immediate:true})
watch(expanded,()=>{requestTab.value='params';sourceOpen.value=''})
function toggleGroup(id:string){const set=new Set(folded.value);if(set.has(id))set.delete(id);else set.add(id);folded.value=set}
function canLeaveStep(){if(invalidBodies.has(expanded.value)||invalidBodies.has(expanded.value+':assert_json')){selectionError.value='请先修正当前步骤的 JSON 配置或字段断言，也可以删除未完成的断言。';return false}selectionError.value='';return true}
function chooseStep(id:string){if(id===expanded.value||canLeaveStep())expanded.value=id}
function openPicker(index?:number,inside=''){if(!canLeaveStep())return;insertAfter.value=index===undefined?'':props.modelValue[index]?.id||'';insertInto.value=inside;pickerOpen.value=true;actionQuery.value=''}
function actionGroup(action:string){if(starts.includes(action))return '控制流程';if(action.startsWith('assert')||action==='wait')return '检查与等待';if(['extract','set_variable','csv'].includes(action))return '数据与变量';if(['python','sleep','screenshot'].includes(action))return '辅助操作';return props.kind==='api'||props.kind==='performance'?'请求':'页面操作'}
const actionGroups=computed(()=>{const groups:Record<string,string[]>={};for(const action of choices.value.filter(a=>!['end','else'].includes(a)&&labels[a]?.includes(actionQuery.value))){const group=actionGroup(action);(groups[group]??=[]).push(action)}return groups})
function brief(s:Record<string,any>){if(s.action==='request')return (s.method||'GET')+' '+(s.path||'/');if(s.selector)return (s.by||'css')+': '+s.selector;if(s.action==='goto'||s.action==='open_tab')return s.path||'/';if(s.action==='repeat')return (s.count||1)+' 次';if(s.action==='foreach')return '每项 → '+(s.variable||'item');if(s.action==='extract')return (s.expression||s.source||'')+' → '+(s.variable||'变量');if(s.action==='assert')return (s.expression||s.source||'响应')+' '+(s.operator||'eq')+' '+JSON.stringify(s.expected);return s.variable||s.value||''}
function displayName(s:Record<string,any>){return /^步骤\s*\d+$/.test(s.name||'')?labels[s.action]:s.name||labels[s.action]}
function checkValidity(s:Record<string,any>,valid:boolean){const key=s.id+':assert_json';if(valid){invalidBodies.delete(key);selectionError.value=''}else invalidBodies.add(key);emit('validity',invalidBodies.size===0)}
const locatorLabels:Record<string,string>={css:'CSS 选择器',role:'角色与名称',label:'表单标签',text:'页面文字',testid:'测试标识',xpath:'XPath','accessibility id':'无障碍标识',id:'资源 ID','android uiautomator':'Android UIAutomator'}
</script>
<template><div class="steps-editor">
<div class="steps-workspace"><aside class="step-outline" aria-label="测试步骤"><div class="outline-heading"><strong>步骤 <span class="muted">{{modelValue.filter(s=>s.action!=='end').length}}</span></strong><button class="icon-button" type="button" aria-label="添加步骤" @click="openPicker()"><AppIcon name="plus" :size="18"/></button></div>
<div v-for="{s,i} in visibleSteps" :key="s.id" class="outline-item" :class="{active:expanded===s.id,disabled:s.enabled===false,control:starts.includes(s.action)}" :style="{'--depth':Math.min(depth(i),5)}"><button v-if="starts.includes(s.action)" class="outline-fold" type="button" :aria-label="(folded.has(s.id)?'展开':'折叠')+'控制块 '+(i+1)" :aria-expanded="!folded.has(s.id)" @click="toggleGroup(s.id)"><AppIcon :name="folded.has(s.id)?'chevron':'down'" :size="13"/></button><button class="outline-select" type="button" :aria-label="'编辑步骤 '+(i+1)+' '+displayName(s)" :aria-pressed="expanded===s.id" @click="chooseStep(s.id)"><span class="outline-number">{{i+1}}</span><span><strong>{{displayName(s)}}</strong><small>{{brief(s)||labels[s.action]}}</small></span></button><button class="outline-insert" type="button" :aria-label="'在步骤 '+(i+1)+' 后插入'" @click="openPicker(i)">＋</button></div><button class="outline-add" type="button" @click="openPicker()"><AppIcon name="plus" :size="16"/>添加步骤</button><details class="outline-help"><summary>变量与源码</summary><p>使用 <code v-pre>{{token}}</code> 引用变量，使用 <code v-pre>{{env.TEST_PASSWORD}}</code> 引用环境变量。每个步骤可查看对应源码。</p></details></aside>
<section class="step-configuration" aria-label="步骤配置"><template v-for="(s,i) in modelValue" :key="s.id"><div v-if="expanded===s.id" class="selected-step"><header class="selected-step-heading"><span class="plain-tag">{{labels[s.action]}}</span><label class="step-enable"><input v-model="s.enabled" type="checkbox" :disabled="['end','else'].includes(s.action)" @change="update"/>启用</label><details class="step-more"><summary aria-label="步骤操作"><AppIcon name="more" :size="19"/></summary><div><button type="button" :disabled="i===0||['end','else'].includes(s.action)" @click="move(i,-1)">上移</button><button type="button" :disabled="i===modelValue.length-1||['end','else'].includes(s.action)" @click="move(i,1)">下移</button><button type="button" :disabled="['end','else'].includes(s.action)" @click="duplicate(i)">复制步骤</button><button type="button" @click="openPicker(i)">在此之后插入</button><button type="button" class="danger" :disabled="s.action==='end'" @click="remove(i)">{{starts.includes(s.action)?'删除整个控制块':'删除步骤'}}</button></div></details></header><label class="field-label step-name-label">步骤名称<input v-model="s.name" :aria-label="'步骤名称 '+(i+1)" @input="update"/></label><p v-if="selectionError" class="inline-error" role="alert">{{selectionError}}</p><p v-if="previewError" class="inline-error" role="alert">{{previewError}}</p><div class="visual-step-body"><template v-if="s.action==='request'">
<div class="request-line"><select v-model="s.method" class="select" aria-label="HTTP 方法" @change="update"><option v-for="m in ['GET','POST','PUT','PATCH','DELETE','HEAD','OPTIONS']" :key="m">{{m}}</option></select><input v-model="s.path" aria-label="接口路径" placeholder="/api/login，相对于所选环境" @input="update"/></div>
<div class="request-tabs" role="tablist" aria-label="请求配置"><button v-for="entry in [{id:'params',label:'参数与请求头'},{id:'body',label:'请求体'},{id:'checks',label:'断言与提取'},{id:'advanced',label:'高级'}]" :key="entry.id" type="button" role="tab" :aria-selected="requestTab===entry.id" :class="{active:requestTab===entry.id}" @click="requestTab=entry.id">{{entry.label}}</button></div>
<div v-show="requestTab==='params'" class="form-grid"><KeyValueEditor :model-value="s.params||{}" label="查询参数" @update:model-value="s.params=$event;update()"/><KeyValueEditor :model-value="s.headers||{}" label="请求头" @update:model-value="s.headers=$event;update()"/></div>
<div v-show="requestTab==='body'" class="form-grid"><label class="field-label">请求体类型<select v-model="s.body_type" class="select" @change="s.body=null;delete bodyDraft[s.id];invalidBodies.delete(s.id);selectionError='';emit('validity',invalidBodies.size===0);update()"><option value="json">JSON</option><option value="form">表单</option><option value="text">文本</option><option v-if="kind==='api'" value="multipart">文件上传</option></select></label><KeyValueEditor v-if="['form','multipart'].includes(s.body_type)" :model-value="s.body||{}" label="表单字段" @update:model-value="s.body=$event;update()"/><label v-else class="field-label">请求体<textarea :value="bodyDraft[s.id]??bodyText(s.body)" rows="6" placeholder='{"login_id":"user","password":"{{env.TEST_PASSWORD}}"}' @input="setBody(s,$event)"/></label><p v-if="invalidBodies.has(s.id)" class="inline-error" role="alert">请求体需要有效的 JSON，请修正后再保存。</p><KeyValueEditor v-if="s.body_type==='multipart'" :model-value="s.uploads||{}" label="文件字段 → 辅助文件名" @update:model-value="s.uploads=$event;update()"/></div>
<div v-show="requestTab==='checks'" class="form-grid"><label class="field-label">预期 HTTP 状态（可选）<input :value="s.expected_status??''" type="number" min="100" max="599" @input="s.expected_status=($event.target as HTMLInputElement).value===''?null:Number(($event.target as HTMLInputElement).value);update()"/></label><JsonAssertionsEditor :model-value="s.assert_json||{}" @update:model-value="s.assert_json=$event;update()" @validity="checkValidity(s,$event)"/><label class="field-label">响应正文正则（可选）<input v-model="s.body_pattern" @input="update"/></label><label v-if="kind==='performance'" class="field-label">单次请求耗时上限（毫秒，可选）<input :value="s.max_response_ms??''" type="number" min="1" @input="s.max_response_ms=($event.target as HTMLInputElement).value===''?null:Number(($event.target as HTMLInputElement).value);update()"/></label><KeyValueEditor v-if="kind==='performance'" :model-value="s.extract_json||{}" label="提取变量：变量名 → JSONPath" @update:model-value="s.extract_json=$event;update()"/></div>
<div v-show="requestTab==='advanced'" class="form-grid"><label class="field-label">跟随重定向<select v-model="s.follow_redirects" class="select" @change="update"><option :value="null">默认（{{kind==='api'?'不跟随':'跟随'}}）</option><option :value="true">跟随</option><option :value="false">不跟随</option></select></label><label class="field-label">连接／读写阶段超时（毫秒）<input v-model.number="s.timeout" type="number" min="100" max="60000" @input="update"/></label><p class="form-hint">该超时控制连接与读写阶段；总耗时另用响应时间断言检查。</p></div>
</template>
<template v-else-if="kind==='api'&&(s.action==='extract'||s.action==='assert')">
<div class="config-grid"><label class="field-label">从哪里取值<select v-model="s.source" class="select" @change="s.query='path';update()"><option value="json">响应 JSON</option><option value="header">响应头</option><option value="status">HTTP 状态码</option><option value="response_time">响应时间（毫秒）</option><option value="text">响应正文文本</option><option value="variable">已有变量</option></select></label>
<label v-if="['json','variable','text'].includes(s.source)" class="field-label">取值方式<select :value="s.query||'path'" class="select" @change="s.query=($event.target as HTMLSelectElement).value;update()"><template v-if="s.source==='text'"><option value="path">全文</option><option value="regex">正则提取</option></template><template v-else><option value="path">简单字段路径</option><option value="jmespath">JMESPath</option><option value="jsonpath">JSONPath</option></template></select></label>
<label v-if="['json','header','variable'].includes(s.source)||s.query==='regex'" class="field-label">{{s.source==='header'?'响应头名称':'表达式'}}<input v-model="s.expression" :placeholder="s.query==='jmespath'?'data.users[?active].id':s.query==='jsonpath'?'$.data.users[*].id':s.query==='regex'?'token=([a-z0-9]+)':'data.token 或 users[0].id'" @input="update"/></label>
<label v-if="s.query==='regex'" class="field-label">正则分组（0 为整个匹配）<input v-model.number="s.match_group" type="number" min="0" max="20" @input="update"/></label>

<label v-if="s.action==='extract'" class="field-label">保存为变量<input v-model="s.variable" placeholder="例如 token" @input="update"/></label>
<template v-else><label class="field-label">比较方式<select v-model="s.operator" class="select" @change="update"><option v-for="(label,key) in {eq:'等于',ne:'不等于',contains:'包含',matches:'正则匹配',gt:'大于',gte:'大于等于',lt:'小于',lte:'小于等于',exists:'存在且非 null',not_exists:'不存在或为 null',length:'长度等于',type:'类型为'}" :key="key" :value="key">{{label}}</option></select></label><label v-if="!['exists','not_exists'].includes(s.operator)" class="field-label">期望值<input :value="typeof s.expected==='string'?s.expected:JSON.stringify(s.expected)" :placeholder="s.operator==='type'?'string / number / boolean / object / array / null':'200、true、文本或 JSON 数组'" @input="setExpected(s,$event)"/></label></template></div>
<p class="form-hint">默认读取最近一次请求。JSONPath 多个匹配返回数组，单个返回该值。JMESPath 适合筛选和投影；它不是 HTTP 协议字段。</p>
</template>
<template v-else-if="s.action==='if'">
<div class="config-grid"><label class="field-label">判断依据<select v-model="s.source" class="select" @change="s.query='path';update()"><option value="variable">已有变量</option><template v-if="kind==='api'"><option value="json">响应 JSON</option><option value="status">HTTP 状态</option><option value="text">响应文本</option><option value="header">响应头</option><option value="response_time">响应时间（毫秒）</option></template><option v-else-if="kind==='web'||kind==='app'" value="element">页面元素</option></select></label>
<template v-if="s.source==='element'"><label class="field-label">定位方式<select v-model="s.by" class="select" @change="update"><option v-for="by in kind==='app'?['accessibility id','id','xpath','android uiautomator']:['css','role','label','text','testid','xpath']" :key="by" :value="by">{{locatorLabels[by]||by}}</option></select></label><label class="field-label">定位内容<input v-model="s.selector" @input="update"/></label><label v-if="s.by==='role'" class="field-label">角色<input v-model="s.role" @input="update"/></label><label class="field-label">元素条件<select v-model="s.condition" class="select" @change="update"><option v-for="(label,key) in {visible:'可见',hidden:'不可见',exists:'存在',enabled:'可用',checked:'已勾选',text:'包含文字'}" :key="key" :value="key">{{label}}</option></select></label><label v-if="s.condition==='text'" class="field-label">包含文字<input v-model="s.value" @input="update"/></label><label v-if="kind==='web'" class="field-label">iframe CSS（可选）<input v-model="s.frame" @input="update"/></label><label v-if="kind==='web'&&['role','label','text'].includes(s.by)" class="field-label">定位文字匹配<select :value="s.exact??true" class="select" @change="s.exact=($event.target as HTMLSelectElement).value==='true';update()"><option value="true">完全匹配</option><option value="false">包含</option></select></label><label v-if="kind==='web'" class="field-label">匹配元素序号（0 起，可选）<input :value="s.nth??''" type="number" min="0" @input="s.nth=($event.target as HTMLInputElement).value===''?null:Number(($event.target as HTMLInputElement).value);update()"/></label></template>
<template v-else><label v-if="kind!=='performance'&&['variable','json','text'].includes(s.source)" class="field-label">取值方式<select v-model="s.query" class="select" @change="update"><template v-if="s.source==='text'"><option value="path">全文</option><option value="regex">正则提取</option></template><template v-else><option value="path">简单字段路径</option><option value="jmespath">JMESPath</option><option value="jsonpath">JSONPath</option></template></select></label><label v-if="s.source==='variable'||s.source==='json'||s.source==='header'||s.query==='regex'" class="field-label">字段路径 / 表达式<input v-model="s.expression" placeholder="变量名称 或 data.status" @input="update"/></label><label v-if="s.query==='regex'" class="field-label">正则分组（0 为整个匹配）<input v-model.number="s.match_group" type="number" min="0" max="20" @input="update"/></label><label class="field-label">比较方式<select v-model="s.operator" class="select" @change="update"><option v-for="(label,key) in {eq:'等于',ne:'不等于',contains:'包含',matches:'正则匹配',exists:'存在',not_exists:'不存在',gt:'大于',gte:'大于等于',lt:'小于',lte:'小于等于'}" :key="key" :value="key">{{label}}</option></select></label></template><label v-if="s.source==='element'?s.condition!=='text':!['exists','not_exists'].includes(s.operator)" class="field-label">期望值（支持 JSON）<input :value="typeof s.expected==='string'?s.expected:JSON.stringify(s.expected)" placeholder="元素条件留空默认 true" @input="setExpected(s,$event)"/></label></div>
<p class="form-hint">条件满足执行块内步骤；不满足进入否则分支。响应和变量立即判断；元素条件按等待上限重试，无效定位器会报错。</p><button v-if="!hasElse(i)" type="button" class="button secondary" @click="addElse(i)">添加否则分支</button>
</template>
<template v-else-if="s.action==='repeat'"><div class="config-grid"><label class="field-label">重复次数<input v-model.number="s.count" type="number" min="1" max="1000" @input="update"/></label><label v-if="kind!=='performance'" class="field-label">索引变量（可选，从 0 起）<input v-model="s.variable" @input="update"/></label></div></template>
<template v-else-if="s.action==='foreach'"><label class="field-label">每项保存为变量<input v-model="s.variable" placeholder="item" @input="update"/></label><label class="field-label">数组或数组变量<textarea :value="bodyText(s.items)" rows="4" placeholder='["a","b"] 或 {{data}}' @change="setItems(s,$event)"/></label></template>
<template v-else-if="s.action==='csv'"><div class="config-grid"><label class="field-label">辅助 CSV 文件名<input v-model="s.value" placeholder="accounts.csv" @input="update"/></label><label class="field-label">变量名（逗号分隔）<input v-model="s.columns" placeholder="login_id,password" @input="update"/></label><label class="field-label">分隔符<input v-model="s.delimiter" maxlength="1" @input="update"/></label><label class="field-label">数据共享<select v-model="s.share_mode" class="select" @change="update"><option value="all">所有用户依次取行</option><option value="thread">每用户独立读取</option></select></label></div><div class="config-grid"><label><input v-model="s.ignore_first_line" type="checkbox" @change="update"/>跳过表头</label><label><input v-model="s.recycle" type="checkbox" @change="update"/>到末尾循环读取</label><label><input v-model="s.stop_thread" type="checkbox" @change="update"/>文件结束后停止用户</label></div><p class="form-hint">文件内容在“辅助文件”上传或编辑，列值供后续请求引用。</p></template>
<template v-else-if="['once','transaction','end','else'].includes(s.action)"><p class="form-hint">{{s.action==='once'?'每个用户在父循环的首次迭代执行此块；通常直接放在线程组下实现仅登录一次。':s.action==='transaction'?'汇总块内请求的事务耗时；HTTP 指标与事务样本分别统计。':s.action==='else'?'条件不满足时执行后续块内步骤。':'此步骤结束对应控制块；删除起始步骤会一并删除整个块。'}}</p></template>
<template v-else-if="['open_tab','switch_tab','close_tab'].includes(s.action)"><label class="field-label">标签页名称<input v-model="s.tab" placeholder="main / detail" @input="update"/></label><label v-if="s.action==='open_tab'" class="field-label">页面路径<input v-model="s.path" placeholder="/login" @input="update"/></label><p class="form-hint">初始页面名 main；新页面需要唯一名称，关闭后回到 main。</p></template>
<template v-else-if="s.action==='press'&&kind==='app'"><label class="field-label">Android 按键<input v-model="s.value" placeholder="ENTER / BACK / HOME / DELETE / TAB / keycode" @input="update"/></label></template>
<template v-else-if="s.action==='set_variable'"><div class="config-grid"><label class="field-label">变量名称<input v-model="s.variable" @input="update"/></label><label class="field-label">变量值（支持 JSON）<input :value="typeof s.expected==='string'?s.expected:JSON.stringify(s.expected)" @input="setExpected(s,$event)"/></label></div></template>
<template v-else-if="s.action==='sleep'"><label class="field-label">暂停时间（毫秒）<input v-model.number="s.duration_ms" type="number" min="0" max="60000" @input="update"/></label><p class="form-hint">固定暂停不会检查页面是否准备好，页面操作优先使用条件等待。</p></template>
<template v-else-if="s.action==='python'"><label class="field-label">此步骤的扩展理由<input v-model="s.reason" placeholder="标准动作尚不能表达的局部逻辑" @input="update"/></label><label class="field-label">Python 代码<textarea v-model="s.python" class="python-step-input" rows="8" spellcheck="false" aria-label="Python 步骤代码" @input="update"/></label><p class="form-hint">直接插入当前测试函数，可使用 rt.variables / rt.value、Web 的 page、APP 的 driver。API 可用 rt.client / rt.response；通过 rt.request 发送请求会更新响应。不要用 return 提前结束用例。执行权限与原生脚本相同。</p></template>
<template v-else-if="s.action==='goto'"><label class="field-label">页面路径<input v-model="s.path" placeholder="/login" @input="update"/></label></template>
<template v-else-if="s.action==='assert_url'"><label class="field-label">页面地址正则<input v-model="s.value" placeholder="/login" @input="update"/></label></template>
<template v-else-if="s.action==='swipe'"><label class="field-label">方向<select v-model="s.direction" class="select" @change="update"><option v-for="d in ['up','down','left','right']" :key="d">{{d}}</option></select></label></template>
<template v-else-if="s.action==='screenshot'"><label class="field-label">截图文件名<input v-model="s.value" placeholder="checkout.png" @input="update"/></label><p class="form-hint">保存到本次运行的报告附件；还会保留测试结束时的页面截图。</p></template>
<template v-else-if="s.action==='dialog'"><label class="field-label">处理下一个弹窗<select v-model="s.value" class="select" @change="update"><option value="accept">确认</option><option value="dismiss">取消</option></select></label><p class="form-hint">放在触发弹窗的点击之前，不会主动打开弹窗。</p></template>
<template v-else-if="!noLocator.includes(s.action)">
<div class="config-grid">
<label class="field-label">定位方式<select v-model="s.by" class="select" @change="update"><option v-for="by in kind==='app'?['accessibility id','id','xpath','android uiautomator']:['css','role','label','text','testid','xpath']" :key="by" :value="by">{{locatorLabels[by]||by}}</option></select></label>
<label v-if="s.by==='role'" class="field-label">角色<input v-model="s.role" placeholder="button、textbox、heading" @input="update"/></label>
<label class="field-label">定位内容<input v-model="s.selector" :placeholder="s.by==='role'?'元素名称，例如 登录':'选择器或元素标识'" @input="update"/></label>
<label v-if="kind==='web'&&['role','label','text'].includes(s.by)" class="field-label">定位文字匹配<select :value="s.exact??true" class="select" @change="s.exact=($event.target as HTMLSelectElement).value==='true';update()"><option value="true">完全匹配</option><option value="false">包含</option></select></label>
<label v-if="s.action==='click_popup'" class="field-label">新标签页名称<input v-model="s.tab" @input="update"/></label><label v-if="s.action==='drag'" class="field-label">目标 CSS 定位器<input v-model="s.target_selector" @input="update"/></label>
<label v-if="['fill','press','select','assert_text','assert_value','assert_attribute','upload','download'].includes(s.action)" class="field-label">{{s.action==='upload'?'辅助文件名':s.action==='download'?'报告中的下载文件名':s.action.startsWith('assert_')?'期望内容':s.action==='press'?'按键，例如 Enter':'输入或选择的内容'}}<input v-model="s.value" @input="update"/></label>
<label v-if="s.action==='extract'" class="field-label">保存为变量<input v-model="s.variable" @input="update"/></label>
<label v-if="s.action==='extract'||s.action==='assert_attribute'" class="field-label">属性名{{s.action==='extract'?'（空读文字，value 读当前输入值）':''}}<input v-model="s.attribute" placeholder="value / href / text ..." @input="update"/></label>
<label v-if="s.action==='assert_count'" class="field-label">预期数量<input v-model.number="s.expected" type="number" min="0" @input="update"/></label>
<label v-if="s.action==='assert_text'" class="field-label">文字断言<select :value="s.text_exact??false" class="select" @change="s.text_exact=($event.target as HTMLSelectElement).value==='true';update()"><option value="false">包含期望文字</option><option value="true">完全相等</option></select></label>
<label v-if="['assert_visible','assert_enabled','assert_checked'].includes(s.action)" class="field-label">预期状态<select :value="s.expected!==false" class="select" @change="s.expected=($event.target as HTMLSelectElement).value==='true';update()"><option value="true">{{s.action==='assert_visible'?'可见':s.action==='assert_checked'?'已勾选':'可用'}}</option><option value="false">{{s.action==='assert_visible'?'不可见':s.action==='assert_checked'?'未勾选':'不可用'}}</option></select></label>
<label v-if="s.action==='wait'" class="field-label">等待直到<select :value="s.state||'visible'" class="select" @change="s.state=($event.target as HTMLSelectElement).value;update()"><option value="visible">元素可见</option><option value="hidden">元素不可见</option><option value="attached">元素出现在 DOM / 页面结构中</option><option value="detached">元素从 DOM / 页面结构中消失</option></select></label>
</div>
<details v-if="kind==='web'" class="locator-options"><summary>定位高级选项</summary><div class="config-grid"><label class="field-label">iframe CSS 选择器（可选）<input v-model="s.frame" placeholder="iframe#payment" @input="update"/></label><label class="field-label">第几个匹配元素（从 0 起，空则要求唯一）<input :value="s.nth??''" type="number" min="0" @input="s.nth=($event.target as HTMLInputElement).value===''?null:Number(($event.target as HTMLInputElement).value);update()"/></label></div></details>
<p class="form-hint">Web 操作和断言自动等待；APP 使用显式等待。</p>
</template>
<label v-if="!['request','set_variable','python','sleep','back','swipe','dialog','repeat','foreach','end','else','once','transaction','csv','switch_tab','close_tab'].includes(s.action)&&!(kind==='api'&&['extract','assert'].includes(s.action))&&!(s.action==='if'&&s.source!=='element')" class="field-label step-timeout">{{s.action==='request'?'连接 / 读写阶段超时（毫秒）':'操作 / 断言等待上限（毫秒）'}}<input v-model.number="s.timeout" type="number" min="100" max="60000" @input="update"/></label>

<button v-if="starts.includes(s.action)||s.action==='else'" class="text-button" type="button" @click="openPicker(undefined,s.id)">在此块内添加步骤</button>
<div class="step-source"><button type="button" class="text-button" :disabled="previewPending||!!previewError||!map(s)?.start" @click="sourceOpen=sourceOpen===s.id?'':s.id">{{previewPending?'正在生成源码…':map(s)?.start?'对应源码 L'+map(s)?.start+'–'+map(s)?.end:s.enabled?'保存新版本后生成逐步映射':'此步骤已禁用'}} {{sourceOpen===s.id?'收起':'查看'}}</button><pre v-if="sourceOpen===s.id&&snippet(s)" class="step-code">{{snippet(s)}}</pre></div>
</div></div></template><div v-if="!modelValue.length" class="empty-state"><AppIcon name="plus" :size="28"/><h3>添加第一个步骤</h3><button class="button secondary" type="button" @click="openPicker()">选择动作</button></div></section></div>
<AppModal :open="pickerOpen" title="添加测试步骤" class="action-picker" @close="pickerOpen=false"><div class="modal-body"><input v-model="actionQuery" aria-label="搜索动作" placeholder="搜索请求、点击、断言…"/><label class="field-label picker-location">插入位置<select v-model="insertInto" class="select" aria-label="添加步骤的位置" @change="insertAfter=''"><option value="">{{insertAfter?'第 '+(modelValue.findIndex(s=>s.id===insertAfter)+1)+' 步之后':'用例末尾'}}</option><option v-for="group in modelValue.filter(s=>starts.includes(s.action)||s.action==='else')" :key="group.id" :value="group.id">{{displayName(group)}} 内</option></select></label><section v-for="(actions,group) in actionGroups" :key="group" class="action-group"><h3>{{group}}</h3><div><button v-for="action in actions" :key="action" class="action-choice" type="button" @click="selected=action;add()">{{labels[action]}}<AppIcon name="plus" :size="15"/></button></div></section><p v-if="!Object.keys(actionGroups).length" class="empty-state">没有匹配的动作</p></div></AppModal>
</div></template>
